def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change_ratio = (v2 - v1) / v1
    projected_value = v2 * (1 + change_ratio)

    return {
        "value": projected_value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "change_ratio": change_ratio,
            "projected_value": projected_value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
